Binary-search the shorter array for a partition whose left-side values are no greater than its right-side values. Call solve(nums1, nums2) directly with ascending numeric arrays and positive combined length.

```javascript
function solve(nums1, nums2) {
  if (nums1.length > nums2.length) {
    [nums1, nums2] = [nums2, nums1];
  }

  const m = nums1.length;
  const n = nums2.length;
  const half = Math.floor((m + n + 1) / 2);
  let low = 0;
  let high = m;

  while (low <= high) {
    const i = low + Math.floor((high - low) / 2);
    const j = half - i;

    const left1 = i === 0 ? -Infinity : nums1[i - 1];
    const right1 = i === m ? Infinity : nums1[i];
    const left2 = j === 0 ? -Infinity : nums2[j - 1];
    const right2 = j === n ? Infinity : nums2[j];

    if (left1 <= right2 && left2 <= right1) {
      const leftMax = Math.max(left1, left2);
      if ((m + n) % 2 === 1) return leftMax;
      const rightMin = Math.min(right1, right2);
      return leftMax / 2 + rightMin / 2;
    }

    if (left1 > right2) {
      high = i - 1;
    } else {
      low = i + 1;
    }
  }
}
```

Time: O(log(min(m,n) + 1)), within the requested O(log(m+n)) target. Extra space: O(1).

